<?php
namespace App\Console\Commands;
use App\Models\School;use App\Models\User;use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Hash;use Illuminate\Support\Facades\Schema;
class BootstrapSchoolCloud extends Command {protected $signature='schoolcloud:bootstrap';protected $description='Provision platform administrator and legacy tenant';public function handle():int{$email=env('ADMIN_EMAIL','hassanisahassan12@gmail.com');$password=env('ADMIN_PASSWORD');if(!$password){$this->error('ADMIN_PASSWORD is required.');return self::FAILURE;}$admin=User::updateOrCreate(['email'=>$email],['name'=>'Isah Hassan Hassan','password'=>Hash::make($password),'is_super_admin'=>true]);$schoolUser=User::updateOrCreate(['email'=>'schooladmin@highflyers.test'],['name'=>'Highflyers Proprietor','password'=>Hash::make($password),'is_super_admin'=>false]);$school=School::firstOrCreate(['slug'=>'highflyers'],['name'=>'Highflyers School','email'=>$email,'tier'=>'premium','subscription_status'=>'active']);DB::table('school_user')->updateOrInsert(['school_id'=>$school->id,'user_id'=>$schoolUser->id],['role'=>'proprietor','custom_permissions'=>json_encode([]),'is_active'=>true,'created_at'=>now(),'updated_at'=>now()]);if(Schema::hasTable('schoolresults_subject'))foreach(DB::table('schoolresults_subject')->get() as $row)DB::table('subjects')->updateOrInsert(['school_id'=>$school->id,'name'=>$row->name,'section'=>$row->section],['display_order'=>$row->display_order,'created_at'=>now(),'updated_at'=>now()]);$this->info("SchoolCloud ready: {$admin->email}");return self::SUCCESS;}}
